        const title = String(post?.title || 'Gematria.Today Blog').trim();
        const description = String(post?.summary || 'Explore gematria research workflows, trusted methodology notes, and interconnected tools from Gematria.Today.').trim();
        const featuredImageUrl = toSharePreviewImageUrl(post?.heroImageUrl || post?.imageUrl || post?.backgroundImageUrl || post?.sliderImageUrl) || toSharePreviewImageUrl(getDefaultBlogHeroImageUrl());

        document.title = title;
        const canonicalEl = document.querySelector('link[rel="canonical"]');
