      const updateBlogChrome = (detailViewActive, requestedTargetPost) => {
        const toolbar = document.getElementById('blogListToolbar');
        if (toolbar) {
          toolbar.classList.toggle('d-none', detailViewActive);
        }
        const breadcrumb = document.getElementById('blogBreadcrumb');
        const breadcrumbCurrent = document.getElementById('blogBreadcrumbCurrent');
        if (breadcrumb && breadcrumbCurrent) {
          if (detailViewActive && requestedTargetPost) {
            breadcrumbCurrent.textContent = String(requestedTargetPost.title || 'Post');
            breadcrumb.classList.remove('d-none');
          } else {
            breadcrumb.classList.add('d-none');
          }
        }
        const progressBar = document.getElementById('blogReadingProgress');
        if (progressBar) {
          const wrap = progressBar.parentElement;
          if (wrap) {
            wrap.classList.toggle('d-none', !detailViewActive);
          }
          if (!detailViewActive) {
            progressBar.style.width = '0%';
          }
        }
      };
      const updatePostsCount = (visibleCount, totalCount, detailViewActive) => {
        const countEl = document.getElementById('blogPostsCount');
        if (!countEl) {
          return;
        }
        if (detailViewActive || !totalCount) {
          countEl.textContent = '';
          return;
        }
        countEl.textContent = visibleCount === totalCount
          ? `${totalCount} post${totalCount === 1 ? '' : 's'}`
          : `Showing ${visibleCount} of ${totalCount} posts`;
      };
      const getPostEditUrl = (post) => {
        const rawId = String(post?.id || '').trim();
        if (rawId) {
          return `/admin-posts.html?editPost=${encodeURIComponent(rawId)}`;
        }
        const rawSlug = String(post?.slug || '').trim();
        return rawSlug ? `/admin-posts.html?editPost=${encodeURIComponent(rawSlug)}` : '/admin-posts.html';
      };

      const sortPostsEditorial = (posts) => {
        const collator = new Intl.Collator(undefined, { sensitivity: 'base' });
        return posts.slice().sort((left, right) => {
          const leftFeatured = isTruthyFlag(left?.featured || left?.isFeatured) ? 1 : 0;
          const rightFeatured = isTruthyFlag(right?.featured || right?.isFeatured) ? 1 : 0;
          if (leftFeatured !== rightFeatured) {
            return rightFeatured - leftFeatured;
          }
          return collator.compare(String(left?.title || ''), String(right?.title || ''));
        });
      };
      function renderPosts(posts) {
        latestPosts = sortPostsEditorial(posts.map((post, index) => ({ ...post, slug: createPostSlug(post, index) })));
        allLoadedPosts = latestPosts.filter((post) => !isHiddenFromMainBlog(post));
        const requestedPostSlug = String(getRequestedPostSlug() || '').trim();
        const requestedPostId = String(getRequestedPostId() || '').trim();
        const detailViewActive = Boolean(requestedPostSlug || requestedPostId);
        const requestedTargetPost = (requestedPostSlug
          ? latestPosts.find((post) => String(post.slug || '').toLowerCase() === requestedPostSlug.toLowerCase())
          : null)
          || (requestedPostId
            ? latestPosts.find((post) => String(post.id || '').trim() === requestedPostId)
            : null);
        latestPosts = latestPosts.filter((post) => {
          if (requestedTargetPost) {
            return String(post.slug || '').toLowerCase() === String(requestedTargetPost.slug || '').toLowerCase();
          }
          if (previewModeActive) {
            return true;
          }
          return !isHiddenFromMainBlog(post);
        });
        renderTagFilters(latestPosts);
        updateBlogChrome(detailViewActive, requestedTargetPost);

        const filteredPosts = detailViewActive ? latestPosts : getVisiblePosts();
        const previewRequestActive = isPreviewRequested();
        const postMarkup = filteredPosts.map((post) => {
          const preRenderedBodyHtml = String(post.renderedBodyHtml || '').trim();
          const summaryText = String(post.summary || '').trim();
          const readMoreHref = `/blog.html?post=${encodeURIComponent(post.slug)}#${encodeURIComponent(post.slug)}`;
          const fallbackRelatedLinks = `<p class="small mb-0">Related: <a class="news-inline-link" href="/calculator.html">Gematria Calculator</a> · <a class="news-inline-link" href="/name-calculator.html">Name Calculator</a> · <a class="news-inline-link" href="/gematria-guide.html">Gematria Guide</a> · <a class="news-inline-link" href="/blog.html">More Blog Posts</a></p>`;
          const renderedBodySource = preRenderedBodyHtml || normalizePostBodyHtml(post.body || '');
          const sanitizedBodyHtml = stripAutoGeneratedHeroMarkup(renderedBodySource);
          const previewImageVersionToken = previewRequestActive
            ? `${post.updatedAt || post.updated_at || post.createdAt || post.id || 'preview'}-${Date.now()}`
            : '';
          const renderedBodyHtml = previewModeActive
            ? appendImageVersionTokenToHtmlImages(sanitizedBodyHtml, previewImageVersionToken)
            : sanitizedBodyHtml;
          const inlineReadMoreMarkup = `<p class="mb-0"><a class="news-inline-link fw-semibold" href="${escapeHtml(readMoreHref)}">Read full post &rarr;</a></p>`;
          const listSummaryHtml = `<p>${escapeHtml(summaryText || 'Open this post to read the full article.')}</p>${inlineReadMoreMarkup}`;
          const bodyHtml = detailViewActive
            ? `${renderedBodyHtml}${fallbackRelatedLinks}`
            : listSummaryHtml;
          const tags = getPostTags(post);
          const tagBadges = [];
          if (previewModeActive && isDraftPost(post)) {
            tagBadges.push('<span class="badge text-bg-secondary">Draft preview</span>');
          }
          if (tags.length) {
            tagBadges.push(...tags.map((tag) => `<button type="button" class="badge text-bg-warning border-0 blog-post-tag" data-tag-filter="${escapeHtml(tag.toLowerCase())}">${escapeHtml(tag)}</button>`));
          } else {
            tagBadges.push('<span class="badge text-bg-warning">Blog Post</span>');
          }
          const tagMarkup = tagBadges.join(' ');
          const coverImageUrl = getPostCoverImageUrl(post);
          const renderedCoverImageUrl = appendImageVersionToken(coverImageUrl, previewImageVersionToken);
          const coverImageMarkup = coverImageUrl
            ? `<figure class="blog-post-image-frame mb-4"><img class="blog-post-image" src="${escapeHtml(renderedCoverImageUrl)}" alt="${escapeHtml(post.title)}" loading="lazy" decoding="async" width="1600" height="900" /></figure>`
            : '';
          const adminEditButtonMarkup = adminSessionActive
            ? `<a class="btn btn-sm btn-outline-primary fw-semibold" href="${escapeHtml(getPostEditUrl(post))}">Edit</a>`
            : '';
          const copyLinkButtonMarkup = `<button type="button" class="btn btn-sm btn-outline-secondary fw-semibold blog-copy-link-button" data-copy-link="${escapeHtml(post.slug)}">Copy link</button>`;
          return `<article id="${escapeHtml(post.slug)}" class="content-panel p-4 p-lg-5 blog-post-card"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><span class="d-flex flex-wrap gap-2">${tagMarkup}</span><span class="text-muted small">${escapeHtml(post.readTime || '')}</span></div>${coverImageMarkup}<div class="blog-post-body d-grid gap-3">${bodyHtml}</div><div class="d-flex flex-wrap justify-content-end align-items-center gap-3 mt-4"><div class="d-flex flex-wrap gap-2">${adminEditButtonMarkup}${copyLinkButtonMarkup}<button type="button" class="btn btn-sm btn-warning fw-semibold share-action-button" data-share-post="${escapeHtml(post.slug)}">Share</button></div></div></article>`;
        });
        const postsContainer = document.getElementById('blogPosts');
        const showSeriesPromo = !detailViewActive && !searchQuery.trim() && !selectedTag;
        const seriesPromoMarkup = showSeriesPromo ? buildSeriesPromoMarkup() : '';
        if (!postMarkup.length && !detailViewActive) {
          postsContainer.innerHTML = `${seriesPromoMarkup}<div class="content-panel p-4 text-muted small">No posts match your filters. <button type="button" class="btn btn-link btn-sm p-0 align-baseline" id="blogClearFiltersButton">Clear filters</button></div>`;
        } else {
          postsContainer.innerHTML = `${seriesPromoMarkup}${postMarkup.join('')}`;
        }
        updatePostsCount(filteredPosts.length, latestPosts.length, detailViewActive);
        if (detailViewActive) {
          const detailCard = postsContainer.querySelector('.blog-post-card');
          buildSeriesStrip(detailCard, requestedTargetPost);
          buildTableOfContents(detailCard);
          enableTocScrollSpy(detailCard);
          buildRelatedPosts(detailCard, requestedTargetPost);
          updateReadingProgressOffset();
          updateReadingProgress();
        }

        if (filteredPosts.length) {
          const requestedSlug = getRequestedPostSlug();
          if (requestedSlug) {
            focusLinkedPost(requestedSlug);
          }
        } else {
          syncBlogLocation('');
        }
      }

      window.addEventListener('hashchange', () => {
        const requestedTag = getRequestedTag();
        if (requestedTag !== selectedTag) {
          selectedTag = requestedTag;
          renderPosts(latestPosts);
        }
        focusLinkedPost(getRequestedPostSlug());
      });
      let searchDebounceHandle = null;
      document.addEventListener('input', (event) => {
        const searchInput = event.target.closest('#blogSearchInput');
        if (!searchInput) {
          return;
        }
        if (searchDebounceHandle) {
          clearTimeout(searchDebounceHandle);
        }
        const value = String(searchInput.value || '');
        searchDebounceHandle = setTimeout(() => {
          searchQuery = value;
          renderPosts(latestPosts);
        }, 120);
      });
      document.addEventListener('click', (event) => {
        const clearFiltersButton = event.target.closest('#blogClearFiltersButton');
        if (clearFiltersButton) {
          searchQuery = '';
          selectedTag = '';
          syncTagLocation('');
          const searchInput = document.getElementById('blogSearchInput');
          if (searchInput) {
            searchInput.value = '';
          }
          renderPosts(latestPosts);
          return;
        }
        const tagFilterToggle = event.target.closest('#blogTagFiltersToggle');
        if (tagFilterToggle) {
          const tagFiltersEl = document.getElementById('blogTagFilters');
          if (tagFiltersEl) {
            tagFiltersEl.classList.toggle('blog-tag-filters--collapsed');
            updateTagFilterOverflowState();
          }
          return;
        }
        const tagFilter = event.target.closest('[data-tag-filter]');
        if (tagFilter) {
          selectedTag = String(tagFilter.dataset.tagFilter || '').trim().toLowerCase();
          syncTagLocation(selectedTag);
          renderPosts(latestPosts);
          return;
        }
        const copyLinkButton = event.target.closest('[data-copy-link]');
        if (copyLinkButton) {
          const slug = String(copyLinkButton.dataset.copyLink || '').trim().toLowerCase();
          const post = latestPosts.find((entry) => entry.slug.toLowerCase() === slug);
          if (post) {
            const shareUrl = buildSharePostUrl(post.slug);
            const restoreLabel = copyLinkButton.textContent;
            const setLabel = (text) => {
              copyLinkButton.textContent = text;
              window.setTimeout(() => {
                copyLinkButton.textContent = restoreLabel;
              }, 1800);
            };
            const writeWithClipboard = navigator.clipboard
              ? navigator.clipboard.writeText(shareUrl)
              : Promise.reject(new Error('Clipboard API unavailable'));
            writeWithClipboard
              .then(() => {
                reportButtonEvent('copy_link_button_click', { source: 'blog_post_card', slug: post.slug });
                setLabel('Copied!');
              })
              .catch(() => {
                setLabel('Press Ctrl+C');
                window.prompt('Copy this link', shareUrl);
              });
          }
          return;
        }
        const shareButton = event.target.closest('[data-share-post]');
        if (shareButton) {
          const slug = String(shareButton.dataset.sharePost || '').trim().toLowerCase();
          const post = latestPosts.find((entry) => entry.slug.toLowerCase() === slug);
          if (post) {
            reportButtonEvent('share_button_click', { source: 'blog_post_card', slug: post.slug });
            shareBlogPost(post).catch(() => {});
          }
          return;
        }
        const postLink = event.target.closest('a[href*="/blog.html?post="], a[href^="/blog/"], a[href^="#"]');
        if (!postLink) {
          return;
        }
        const url = new URL(postLink.href, window.location.origin);
        const pathMatch = url.pathname.match(/^\/blog\/([^/?#]+)/i);
        if (url.pathname !== '/blog.html' && !pathMatch) {
          return;
        }
        const linkedSlug = pathMatch ? decodeURIComponent(pathMatch[1]) : (url.searchParams.get('post') || url.hash.slice(1));
        window.setTimeout(() => focusLinkedPost(linkedSlug), 0);
      });
      window.addEventListener('resize', () => window.requestAnimationFrame(updateTagFilterOverflowState));
      document.addEventListener('keydown', (event) => {
        if (event.key !== '/' || event.metaKey || event.ctrlKey || event.altKey) {
          return;
        }
        const target = event.target;
        const tagName = target && target.tagName;
        if (tagName === 'INPUT' || tagName === 'TEXTAREA' || tagName === 'SELECT' || (target && target.isContentEditable)) {
          return;
        }
        const searchInput = document.getElementById('blogSearchInput');
        if (!searchInput || searchInput.offsetParent === null) {
          return;
        }
        event.preventDefault();
        searchInput.focus();
        searchInput.select();
      });
      let readingProgressRafHandle = null;
      const scheduleReadingProgressUpdate = () => {
        if (readingProgressRafHandle) {
          return;
        }
        readingProgressRafHandle = window.requestAnimationFrame(() => {
          readingProgressRafHandle = null;
          updateReadingProgress();
        });
      };
      window.addEventListener('scroll', scheduleReadingProgressUpdate, { passive: true });
      window.addEventListener('resize', () => {
        updateReadingProgressOffset();
        scheduleReadingProgressUpdate();
      }, { passive: true });
      updateReadingProgressOffset();
      const navbarToggler = document.querySelector('.navbar-toggler');
      if (navbarToggler) {
        navbarToggler.addEventListener('click', () => {
          window.setTimeout(updateReadingProgressOffset, 350);
        });
      }

      selectedTag = getRequestedTag();

      const applyStaticContentPromise = fetch('/api/public-static-content?page=blog')
        .then((response) => response.ok ? response.json() : Promise.reject(new Error('Failed to load static content')))
        .then((payload) => {
          const content = payload?.content || {};
          if (content.seoTitle) {
            document.title = content.seoTitle;
            const seoTitleNode = document.getElementById('pageSeoTitle');
            if (seoTitleNode) seoTitleNode.textContent = content.seoTitle;
          }
          if (content.metaDescription) {
            const metaNode = document.getElementById('pageMetaDescription');
            if (metaNode) metaNode.setAttribute('content', content.metaDescription);
          }
          if (content.heroHeadline) {
            const heroHeadlineNode = document.getElementById('heroHeadlinePrimary');
            if (heroHeadlineNode) heroHeadlineNode.textContent = content.heroHeadline;
          }
          if (content.heroBody) {
            const heroBodyNode = document.getElementById('heroBodyPrimary');
            if (heroBodyNode) heroBodyNode.textContent = content.heroBody;
          }
          const heroHeadlineSecondaryNode = document.getElementById('heroHeadlineSecondary');
          if (heroHeadlineSecondaryNode && content.heroHeadlineSecondary) {
            heroHeadlineSecondaryNode.textContent = content.heroHeadlineSecondary;
            heroHeadlineSecondaryNode.classList.remove('d-none');
          }
        })
        .catch(() => {});

      const fetchPublishedPosts = async ({ offset = 0 } = {}) => {
        const requestUrl = new URL('/api/public-posts', window.location.origin);
        const requestedPostId = String(getRequestedPostId() || '').trim();
        const requestedPostSlug = String(getRequestedPostSlug() || '').trim();
        if (requestedPostId) {
          requestUrl.searchParams.set('id', requestedPostId);
        } else if (requestedPostSlug) {
          requestUrl.searchParams.set('slug', requestedPostSlug);
        } else {
          requestUrl.searchParams.set('limit', String(BLOG_LIST_PAGE_LIMIT));
          requestUrl.searchParams.set('offset', String(Math.max(0, Number(offset) || 0)));
        }
        if (isPreviewRequested()) {
          requestUrl.searchParams.set('preview', 'true');
        }
        const response = await fetch(requestUrl.toString());
        if (!response.ok) {
          throw new Error('Failed to load published posts');
        }
        return response.json();
      };
      const checkAdminSession = async () => {
        try {
          const response = await fetch('/api/admin-session');
          if (!response.ok) {
            adminSessionActive = false;
            return;
          }
          const payload = await response.json();
          adminSessionActive = Boolean(payload?.authenticated && payload?.user);
        } catch (_) {
          adminSessionActive = false;
        }
      };

      const mergeWithFallbackPosts = (items = [], { includeFallback = true } = {}) => {
        const mergedPosts = [];
        const seenSlugs = new Set();
        const seenTitles = new Set();
        const sourceItems = includeFallback ? [...items, ...fallbackPosts] : [...items];
        sourceItems.forEach((post, index) => {
          const slug = createPostSlug(post, index).toLowerCase();
          const normalizedTitle = String(post?.title || '').trim().toLowerCase();
          if (seenSlugs.has(slug)) {
            return;
          }
          if (normalizedTitle && seenTitles.has(normalizedTitle)) {
            return;
          }
          seenSlugs.add(slug);
          if (normalizedTitle) {
            seenTitles.add(normalizedTitle);
          }
          mergedPosts.push(post);
        });
        return mergedPosts;
      };
      const mergeUniquePosts = (items = []) => mergeWithFallbackPosts(items, { includeFallback: false });

      // When the URL targets a specific post and that post exists in the fallback set,
      // render it immediately so the reader sees content instead of the loading skeleton
      // while the API request is still in flight. The Promise.all below will re-render
      // once the API response arrives.
      (() => {
        const initialRequestedSlug = String(getRequestedPostSlug() || '').trim().toLowerCase();
        if (!initialRequestedSlug) {
          return;
        }
        const fallbackMatch = fallbackPosts.find((post, index) =>
          createPostSlug(post, index).toLowerCase() === initialRequestedSlug
        );
        if (fallbackMatch) {
          renderPosts([fallbackMatch]);
        }
      })();

      const renderPostsPromise = Promise.all([
        checkAdminSession(),
        fetchPublishedPosts({ offset: 0 })
      ])
        .then(([, payload]) => {
          const publishedItems = Array.isArray(payload?.items) ? payload.items : [];
          loadedPublishedPosts = mergeUniquePosts(publishedItems);
          previewModeActive = Boolean(payload?.previewMode);
          hasMorePublishedPosts = Boolean(payload?.hasMore);
          paginationOffset = loadedPublishedPosts.length;
          const previewNotice = document.getElementById('blogPreviewNotice');
          if (previewNotice) {
            previewNotice.classList.toggle('d-none', !previewModeActive);
          }
          const hasRequestedPost = Boolean(getRequestedPostSlug() || getRequestedPostId());
          const mergedPosts = mergeWithFallbackPosts(loadedPublishedPosts);
          selectedTag = getRequestedTag();
          const fallbackSet = previewModeActive || hasRequestedPost ? [] : fallbackPosts;
          renderPosts(mergedPosts.length ? mergedPosts : fallbackSet);
          updateLoadMoreControl();
        })
        .catch(() => {
          previewModeActive = false;
          selectedTag = getRequestedTag();
          hasMorePublishedPosts = false;
          paginationOffset = 0;
          loadedPublishedPosts = [];
          renderPosts(fallbackPosts);
          updateLoadMoreControl();
        });

      document.getElementById('blogLoadMoreButton')?.addEventListener('click', async () => {
        if (loadingMorePosts || !hasMorePublishedPosts) {
          return;
        }
        loadingMorePosts = true;
        updateLoadMoreControl();
        try {
          const payload = await fetchPublishedPosts({ offset: paginationOffset });
          const publishedItems = Array.isArray(payload?.items) ? payload.items : [];
          loadedPublishedPosts = mergeUniquePosts([...loadedPublishedPosts, ...publishedItems]);
          paginationOffset = loadedPublishedPosts.length;
          hasMorePublishedPosts = Boolean(payload?.hasMore);
          renderPosts(mergeWithFallbackPosts(loadedPublishedPosts));
        } catch (_) {
          hasMorePublishedPosts = false;
        } finally {
          loadingMorePosts = false;
          updateLoadMoreControl();
        }
      });

      void applyStaticContentPromise;
      void renderPostsPromise;
